// === Tab: Building ===
class Building {
	constructor(x = 0, y = 0, w = 0) {
		//
		this.x = x || ~~(random(-0.1, 1.1) * width);
		this.y = y || ~~(randomGaussian(cy, S / 4));
		this.w = w || ~~(random(0.1, 0.2) * S * 0.5) * 2;
		this.h = ~~max(random(0.5, 1.5) * height, height - this.y);
		this.fillClr = lerpColor(color(random(["gray", "DarkSlateGray", "DarkSlateBlue", "MidnightBlue"])), color("#001"), this.y / height);
		this.tx = ~~random(4, 15 + 1);
		this.ty = ~~random(5, 11 + 1);
		this.dx = ~~random(3, 8 + 1);
		this.dy = ~~random(3, 8 + 1);
		this.numX = ~~((this.w - this.dx) / (this.tx + this.dx));
		this.numY = ~~((this.h - this.dy) / (this.ty + this.dy));
		this.ox = this.dx + ~~((this.w - this.dx - this.numX * (this.tx + this.dx)) / 2)
		this.oy = this.dy;
		this.loft = ~~random(5);
		this.hall = ~~random(5);
		// console.log(this);
	}

	draw() {
		//
		push()
		translate(this.x, this.y);

		const sh = 0.14
		// shearY(-2 * sh);
		for (let i = 0; i < 2; i++) {

			noStroke();
			fill(this.fillClr);
			fill(BG);
			stroke(FG);
			strokeWeight(2);

			if (i == 0) {
				scale(-0.5, 1)
				shearY(2 * sh);
				rect(0, 0, this.w, this.h);

				line(this.w+4, this.ty, this.w+4, this.h);
				stroke(BG)
				line(this.w+2, this.ty, this.w+2, this.h);
			} else {
				scale(-2, 1)
				shearY(7.5 * sh);
				rect(0, 0, this.w, this.h);

				line(this.w+4, this.ty, this.w+4, this.h);
				stroke(BG)
				line(this.w+2, this.ty, this.w+2, this.h);
			}
			noStroke();
			for (let j = 0, y = this.oy; j < this.numY; j++, y += this.ty + this.dy) {
				for (let i = 0, x = this.ox; i < this.numX; i++, x += this.tx + this.dx) {
					const ns = noise(x, y);
					fill(ns < 0.35 ? BG : FG);
					if (ns < 0.2) stroke(FG);
					// if (i === 0 && (j < this.loft || j > this.numY - this.hall)) {
					if (i === 0 && random() < 0.15) {
						rect(x, y, this.numX * (this.tx + this.dx) - this.dx, this.ty)
						// break;
					}
					rect(x, y, this.tx, this.ty)
					noStroke()
				}
			}

			shearY(3 * sh);
		}
		pop();
	}
}

