// === Tab: mySketch ===
// https://genuary.art/prompts#jan8
// A City. Create a generative metropolis.

const FG = "white", FGA = "#FFFFFF40", BG = "tan";
let font, fontSze;
let S, cx, cy, NUM = 9;

async function setup() {
	createCanvas(windowWidth, windowHeight);
	describe(`grid of layers of hashed combined merged points`);

	font = await loadFont("https://fonts.googleapis.com/css2?family=Bitcount+Prop+Single+Ink:wght@100..900&family=Noto+Sans:ital,wght@0,100..900;1,100..900&family=Sixtyfour:SCAN@-53&display=swap");
	textFont(font);
	textAlign(LEFT, TOP);

	S = max(width, height);
	fontSze = Math.ceil(S / 50);
	fontSze = ~~(fontSze/8)*8;
	textSize(fontSze);
	cx = width/2;
	cy = height/2;


	noStroke();
	fill(FG);

	drawScene();
}

function drawScene() {
	background("tan");

	push();
		stroke(FGA);
		strokeCap(PROJECT);
		for (let i = 0; i < NUM; i++) {
			strokeWeight(random(0.05, 0.1)*S)
			const vec = createVector(0, -height * 2)
			vec.rotate(random(-1, 1));
			line(width/2, height, width/2 + vec.x, height + vec.y)
		}
	pop();

	let buildings = [];
	for (let  i = 0; i < NUM; i++) {
		let b = new Building()
		buildings.push(b);
		while (random() < 0.5) {
			b = new Building(b.x + b.w/8, b.y-S/5, b.w/2)
			buildings.push(b);			
		}
	}

	buildings.sort((a, b) => a.y - b.y);
	for (const b of buildings) {
		b.draw();
	}

	msg(`@epibyte #genuary2608 "Skyline": generative Metropolis`)
}

function mousePressed() {
	if (mouseButton.left) drawScene();
}

function msg(txt) {
	push();
	noStroke();
	fill(FG);
	rect(0, 0, width, fontSze + 2)

	txt += "          ";
	const startIdx = ~~(frameCount / 12) % txt.length;

	txt += txt;
	let croppedTxt = "";
	for (let i = startIdx; i < txt.length; i++) croppedTxt += txt[i];

	fill(BG);
	text(croppedTxt, 0, 1);

	pop();
}

